#!/usr/bin/env python3
"""Cross-reference the raylib 6.0 manifest against MeowyRender's public API.

Parses include/meowyrender/*.hpp for declared free-function names in the
meowyrender namespace, then classifies each raylib entry as:
  missing               - no MeowyRender declaration of that name
  implemented-unverified - declared (and defined) but no dedicated conformance/
                           behavioral test recorded yet
  verified              - declared + covered by a conformance/behavioral test
  platform-unavailable  - intentionally not provided (recorded in overrides)

Status upgrades (implemented-unverified -> verified) and intentional
differences are read from tests/compat/parity_overrides.json so the report
reflects real evidence, not just name matching. Name matching alone NEVER
counts as verified.
"""
import json, re, os

HERE = os.path.dirname(__file__)
ROOT = os.path.join(HERE, "..", "..")
MANIFEST = os.path.join(HERE, "raylib6_manifest.json")
OVERRIDES = os.path.join(HERE, "parity_overrides.json")
REPORT = os.path.join(ROOT, "docs", "RAYLIB6_PARITY.md")
HEADERS = [
    os.path.join(ROOT, "include", "meowyrender", "meowyrender.hpp"),
    os.path.join(ROOT, "include", "meowyrender", "mr_math.hpp"),
    os.path.join(ROOT, "include", "meowyrender", "mr_types.hpp"),
    os.path.join(ROOT, "include", "meowyrender", "mr_input.hpp"),
]

def declared_names():
    names = set()
    decl = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\(")
    for h in HEADERS:
        if not os.path.exists(h):
            continue
        with open(h, encoding="utf-8", errors="replace") as f:
            for line in f:
                s = line.strip()
                if s.startswith("//") or s.startswith("*") or s.startswith("/*"):
                    continue
                # A declaration line ends with ');' or '(' continuation and is
                # not a call (calls are inside function bodies which the public
                # header does not contain).
                for m in decl.finditer(line):
                    names.add(m.group(1))
    # Drop obvious keywords/type constructors.
    for kw in ("if","for","while","switch","return","sizeof","static_cast",
               "reinterpret_cast","const_cast","nodiscard","noexcept"):
        names.discard(kw)
    return names

def main():
    manifest = json.load(open(MANIFEST))
    overrides = json.load(open(OVERRIDES)) if os.path.exists(OVERRIDES) else {}
    verified = set(overrides.get("verified", []))
    platform_na = overrides.get("platform_unavailable", {})   # name -> reason
    intentional_noop = overrides.get("intentional_noop", {})  # name -> reason (correct no-op)
    aliases = overrides.get("aliases", {})                    # raylib name -> mr name
    intentional = overrides.get("intentional_difference", {}) # name -> note

    have = declared_names()

    rows = []
    counts = {"missing":0, "implemented-unverified":0, "verified":0, "platform-unavailable":0, "intentional-noop":0}
    by_module = {}
    for fn in manifest["functions"]:
        name = fn["name"]
        mrname = aliases.get(name, name)
        if name in platform_na:
            status = "platform-unavailable"
        elif name in intentional_noop:
            status = "intentional-noop"
        elif mrname not in have:
            status = "missing"
        elif name in verified:
            status = "verified"
        else:
            status = "implemented-unverified"
        counts[status] += 1
        mod = fn["module"]
        by_module.setdefault(mod, {"missing":0,"implemented-unverified":0,"verified":0,"platform-unavailable":0,"intentional-noop":0})
        by_module[mod][status] += 1
        note = intentional.get(name, "") or platform_na.get(name, "") or intentional_noop.get(name, "")
        rows.append((mod, name, status, fn["signature"], note))

    total = len(manifest["functions"])
    # ---- write report ----
    with open(REPORT, "w") as f:
        p = manifest["provenance"]
        f.write("# raylib 6.0 API parity report\n\n")
        f.write("Auto-generated by `tests/compat/parity_report.py`. Do not edit by hand.\n\n")
        f.write(f"**Reference:** raylib `{p['tag']}` (commit `{p['commit']}`, version {p['version']}), "
                f"extracted from the pinned public headers.\n\n")
        f.write("Statuses: **missing** (no declaration), **implemented-unverified** "
                "(declared + defined + non-stub, no dedicated test yet), **verified** "
                "(declared + covered by a conformance/behavioral test), "
                "**platform-unavailable** (a capability genuinely not implementable on "
                "this backend; a documented no-op), **intentional-noop** (a VALID "
                "ARCHITECTURAL no-op: the function is fully supported but has no work to "
                "do here because the engine handles it differently -- e.g. music streams "
                "on the audio thread, or a value-type config owns no resources -- verified "
                "by lifecycle tests, NOT an unsupported gap). Every non-`missing` "
                "function has a REAL definition (enforced by the anti-stub gate in "
                "`conformance_check.py`); name matching alone never counts as verified.\n\n")
        f.write(f"## Totals ({total} raylib functions)\n\n")
        f.write("| Status | Count | % |\n|---|---|---|\n")
        for k in ("verified","implemented-unverified","missing","platform-unavailable","intentional-noop"):
            f.write(f"| {k} | {counts[k]} | {100*counts[k]/total:.1f}% |\n")
        f.write("\n> Declaration coverage is NOT the same as behavioral compatibility. "
                "Only `verified` reflects a passing test.\n\n")
        f.write("## By module\n\n")
        f.write("| Module | verified | impl-unverified | missing | platform-NA | noop | total |\n|---|---|---|---|---|---|---|\n")
        for mod in sorted(by_module):
            c = by_module[mod]; t = sum(c.values())
            f.write(f"| {mod} | {c['verified']} | {c['implemented-unverified']} | {c['missing']} | {c['platform-unavailable']} | {c['intentional-noop']} | {t} |\n")
        f.write(f"\nraymath functions in reference: {len(manifest['raymath_functions'])}; "
                f"enums: {len(manifest['enums'])}; callbacks: {len(manifest['callbacks'])}.\n\n")
        f.write("## Per-function status\n\n")
        f.write("| Module | raylib function | status | note |\n|---|---|---|---|\n")
        for mod, name, status, sig, note in sorted(rows):
            f.write(f"| {mod} | `{name}` | {status} | {note} |\n")

    print(f"total={total}", {k:counts[k] for k in counts})
    print("report ->", os.path.relpath(REPORT, ROOT))

if __name__ == "__main__":
    main()
